arguments.command:
curl -s -X POST "https://slack.com/api/conversations.list" -H "Authorization: Bearer <TOKEN>" --data-urlencode "types=public_channel,private_channel" --data-urlencode "exclude_archived=false" --data-urlencode "limit=1000" | python3 -c "
import json,sys,datetime
d=json.load(sys.stdin)
if not d.get('ok'):
    print('ERR', d)
else:
    for c in d['channels']:
        created = c.get('created',0)
        print(c['id'], '|', c.get('name'), '|', 'private' if c.get('is_private') else 'public', '| created:', datetime.datetime.utcfromtimestamp(created).strftime('%Y-%m-%d') if created else '?', '| is_archived:', c.get('is_archived'))
"

